"use strict";

const createGitRepositoryService = require("./lib/git-repos");

module.exports = function(RED) {
    const {listRepositories, listBranches, resolveRepository, fetchRemotes} = createGitRepositoryService(RED.settings);

    function GitListNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on("input", async function(msg, send, done) {
            try {
                if (config.mode === "formData") {
                    const repositories = await listRepositories();
                    const branches = Object.create(null);
                    for (const repository of repositories) {
                        await fetchRemotes(repository.path);
                        branches[repository.name] = (await listBranches(repository.path)).map(branch => ({label: branch.name, value: branch.ref}));
                    }
                    msg.payload = {
                        repositories: repositories.map(repository => ({label: repository.name, value: repository.name})),
                        branches
                    };
                } else if (config.mode === "branches") {
                    const name = RED.util.evaluateNodeProperty(config.repository || "payload.repository", config.repositoryType || "msg", node, msg);
                    const repository = await resolveRepository(name);
                    await fetchRemotes(repository.path);
                    msg.options = (await listBranches(repository.path)).map(branch => ({label: branch.name, value: branch.ref}));
                } else {
                    const repositories = await listRepositories();
                    for (const repository of repositories) {
                        await fetchRemotes(repository.path);
                    }
                    msg.options = repositories.map(repository => ({label: repository.name, value: repository.name}));
                }
                node.status({});
                send(msg);
                done();
            } catch (error) {
                node.status({fill: "red", shape: "ring", text: "Git options unavailable"});
                done(error);
            }
        });
    }

    RED.nodes.registerType("git list", GitListNode);
};
